1	import React, { useState, useEffect } from "react";
2	import { Plus, AlertTriangle, Calendar, Package } from "lucide-react";
3	import { Button } from "@/shared/ui/button";
4	import { Input } from "@/shared/ui/input";
5	import { Badge } from "@/shared/ui/badge";
6	import { Popover, PopoverContent, PopoverTrigger } from "@/shared/ui/popover";
7	import { Calendar as CalendarComponent } from "@/shared/ui/calendar";
8	import { format, addDays, parseISO } from "date-fns";
9	import { cn } from "@/shared/lib/utils";
10	import { supabase } from "@/integrations/supabase/client";
11	import { useToast } from "@/shared/hooks/use-toast";
12	import { handleError } from '@/shared/lib/error-handler';
13	import { isLoteRecente } from '@/shared/lib/lote-recency';
14	
15	interface StockBatch {
16	    id: string; // lote_id
17	    codigo: string;
18	    data_validade: string;
19	    data_fabricacao: string | null;
20	    created_at: string | null;
21	}
22	
23	interface BatchListProps {
24	    produtoId: number;
25	    storeId: number;
26	    produtoNome: string;
27	    diasValidadePadrao?: number;
28	    onUpdate?: () => void;
29	}
30	
31	export function BatchList({ produtoId, storeId, produtoNome, diasValidadePadrao, onUpdate }: BatchListProps) {
32	    const [batches, setBatches] = useState<StockBatch[]>([]);
33	    const [loading, setLoading] = useState(false);
34	    // Lotes antigos ficam ocultos por padrão (não devem ser impressos por engano).
35	    const [showOldBatches, setShowOldBatches] = useState(false);
36	
37	    // New Batch Form
38	    const [newFabricacao, setNewFabricacao] = useState<Date | undefined>(new Date());
39	    const [newValidade, setNewValidade] = useState<Date | undefined>(
40	        diasValidadePadrao ? addDays(new Date(), diasValidadePadrao) : undefined
41	    );
42	    const [isAdding, setIsAdding] = useState(false);
43	
44	    const { toast } = useToast();
45	
46	    useEffect(() => {
47	        fetchBatches();
48	    }, [produtoId, storeId]);
49	
50	    useEffect(() => {
51	        if (newFabricacao && diasValidadePadrao) {
52	            setNewValidade(addDays(newFabricacao, diasValidadePadrao));
53	        }
54	    }, [newFabricacao, diasValidadePadrao]);
55	
56	    const fetchBatches = async () => {
57	        setLoading(true);
58	        try {
59	            const { data, error } = await supabase
60	                .from('lotes')
61	                .select(`
62	                    id,
63	                    codigo,
64	                    data_validade,
65	                    data_fabricacao,
66	                    created_at
67	                `)
68	                .eq('produto_id', produtoId)
69	                .eq('loja_id', storeId);
70	
71	            if (error) throw error;
72	
73	            const sorted = ((data || []) as any[]).sort((a, b) => {
74	                // Sort by creation or validity? Let's sort by validity descending (newest expiry first)
75	                const dateA = new Date(a.data_validade).getTime();
76	                const dateB = new Date(b.data_validade).getTime();
77	                return dateB - dateA; // Descending
78	            });
79	
80	            setBatches(sorted);
81	
82	        } catch (error) {
83	            handleError(error, { domain: 'logistica', operation: 'fetchBatches', showToast: false });
84	        } finally {
85	            setLoading(false);
86	        }
87	    };
88	
89	    const handleAddBatch = async () => {
90	        if (!newFabricacao || !newValidade) {
91	            toast({ title: "Preencha todos os campos", variant: "destructive" });
92	            return;
93	        }
94	
95	        const fabricacaoStr = format(newFabricacao, 'ddMMyyyy');
96	        // Removed time from batch code to make it cleaner (requested by user)
97	        // Old format: L{ddMMyyyy}{HHmm} -> L270220261430
98	        // New format: L{ddMMyyyy} -> L27022026
99	        const generatedLoteCode = `L${fabricacaoStr}`;
100	
101	        try {
102	            // Criação idempotente: reaproveita o lote existente (mesmo produto+código)
103	            // em vez de criar um id divergente. Evita orfanizar etiquetas já impressas.
104	            const { error: loteError } = await (supabase.rpc as any)('find_or_create_lote', {
105	                p_produto_id: produtoId,
106	                p_codigo: generatedLoteCode,
107	                p_data_validade: format(newValidade, 'yyyy-MM-dd'),
108	                p_data_fabricacao: format(newFabricacao, 'yyyy-MM-dd'),
109	                p_loja_id: storeId,
110	            });
111	
112	            if (loteError) throw loteError;
113	
114	            // NÃO criar estoque_lotes com quantidade=0 na criação do lote.
115	            // O trigger sync_estoque_from_lotes calcula SUM(quantidade) e zeraria
116	            // o estoque existente. A row em estoque_lotes deve ser criada
117	            // apenas quando houver entrada real de quantidade (via bipe/recebimento).
118	            // Hardened 2026-05-20.
119	
120	            toast({ title: `Lote ${generatedLoteCode} criado com sucesso!` });
121	
122	            setNewFabricacao(new Date());
123	            setIsAdding(false);
124	
125	            fetchBatches();
126	            onUpdate?.();
127	
128	        } catch (e: any) {
129	            handleError(e, { domain: 'logistica', operation: 'addBatch', showToast: false });
130	            toast({
131	                title: "Erro ao criar lote",
132	                description: e.message || "Verifique os dados e tente novamente",
133	                variant: "destructive"
134	            });
135	        }
136	    };
137	
138	    // Lote é identidade permanente (produto + código + validade) e é referenciado
139	    // por movimentações e etiquetas_qr. Apagar lote orfaniza etiquetas (FK SET NULL)
140	    // e quebra inserts de movimentação (23503). Por isso NÃO existe mais excluir
141	    // lote: a caixa apenas se MOVE (entrada/saída). Cf. modelo de logística.
142	
143	    // Helper to format date avoiding timezone issues (treats YYYY-MM-DD as local date)
144	    const formatDate = (dateStr: string) => {
145	        if (!dateStr) return '--/--/----';
146	        // Append time to force local time interpretation or avoid UTC shift if browser is behind UTC
147	        // The safest way for display is to parse the parts manually or append T12:00:00
148	        const date = new Date(dateStr + 'T12:00:00'); 
149	        return format(date, "dd/MM/yyyy");
150	    };
151	
152	    const getExpiryStatus = (dateStr: string) => {
153	        const today = new Date();
154	        const expiry = new Date(dateStr + 'T12:00:00'); // Consistent parsing
155	        const daysUntil = (expiry.getTime() - today.getTime()) / (1000 * 3600 * 24);
156	
157	        if (daysUntil < 0) return { color: "text-red-600 bg-red-50 border-red-200", label: "Vencido", icon: AlertTriangle };
158	        if (daysUntil < 30) return { color: "text-orange-600 bg-orange-50 border-orange-200", label: "Vence em breve", icon: AlertTriangle };
159	        return { color: "text-green-600 bg-green-50 border-green-200", label: "Ok", icon: Calendar };
160	    };
161	
162	    // Esconde lotes antigos por padrão; o toggle revela todos (rastreabilidade).
163	    const recentBatches = batches.filter(b => isLoteRecente(b.data_fabricacao, b.created_at));
164	    const hiddenOldCount = batches.length - recentBatches.length;
165	    const visibleBatches = showOldBatches ? batches : recentBatches;
166	
167	    return (
168	        <div className="w-full bg-white/40 dark:bg-black/20 rounded-xl border border-[#57715B]/10 p-4 space-y-4">
169	            <div className="flex items-center justify-between">
170	                <h4 className="text-sm font-bold text-[#57715B] dark:text-[#E6DCCF] uppercase tracking-wider flex items-center gap-2">
171	                    <Package className="w-4 h-4" /> Gestão de Lotes
172	                </h4>
173	                <Button
174	                    variant="outline"
175	                    size="sm"
176	                    onClick={() => setIsAdding(!isAdding)}
177	                    className="h-7 text-xs gap-1 border-[#57715B]/30 text-[#57715B] hover:bg-[#57715B]/10"
178	                >
179	                    <Plus className="w-3 h-3" /> {isAdding ? "Cancelar" : "Novo Lote"}
180	                </Button>
181	            </div>
182	
183	            {(hiddenOldCount > 0 || showOldBatches) && (
184	                <button
185	                    type="button"
186	                    data-mia-skip
187	                    onClick={() => setShowOldBatches(v => !v)}
188	                    className="block w-fit text-[11px] text-muted-foreground hover:text-[#57715B] underline underline-offset-2"
189	                >
190	                    {showOldBatches
191	                        ? 'Ocultar lotes antigos'
192	                        : `Mostrar lotes antigos (${hiddenOldCount})`}
193	                </button>
194	            )}
195	
196	            {isAdding && (
197	                <div className="bg-white/60 dark:bg-black/40 p-3 rounded-lg border border-[#57715B]/10 space-y-3 animate-in slide-in-from-top-2">
198	                    <div className="grid grid-cols-1 sm:grid-cols-3 gap-2">
199	                        <Popover>
200	                            <PopoverTrigger asChild>
201	                                <Button variant="outline" className={cn("h-8 text-xs justify-start text-left font-normal", !newFabricacao && "text-muted-foreground")}>
202	                                    <Calendar className="mr-2 h-3 w-3" />
203	                                    {newFabricacao ? format(newFabricacao, "dd/MM/yyyy") : "Fabricação"}
204	                                </Button>
205	                            </PopoverTrigger>
206	                            <PopoverContent className="w-auto p-0">
207	                                <CalendarComponent mode="single" selected={newFabricacao} onSelect={setNewFabricacao} initialFocus />
208	                            </PopoverContent>
209	                        </Popover>
210	                        <Popover>
211	                            <PopoverTrigger asChild>
212	                                <Button variant="outline" className={cn("h-8 text-xs justify-start text-left font-normal", !newValidade && "text-muted-foreground")}>
213	                                    <Calendar className="mr-2 h-3 w-3" />
214	                                    {newValidade ? format(newValidade, "dd/MM/yyyy") : "Validade"}
215	                                </Button>
216	                            </PopoverTrigger>
217	                            <PopoverContent className="w-auto p-0">
218	                                <CalendarComponent mode="single" selected={newValidade} onSelect={setNewValidade} initialFocus />
219	                            </PopoverContent>
220	                        </Popover>
221	                    </div>
222	                    <Button data-mia-action="add-batch" size="sm" onClick={handleAddBatch} className="w-full h-7 bg-[#57715B] text-white hover:bg-[#57715B]/90 text-xs">
223	                        Criar Lote (Sem Saldo)
224	                    </Button>
225	                </div>
226	            )}
227	
228	            <div className="space-y-2 max-h-[60vh] overflow-y-auto pr-1">
229	                {visibleBatches.length === 0 ? (
230	                    <div className="text-center py-4 text-xs text-muted-foreground bg-black/5 rounded-lg border border-dashed border-black/10">
231	                        {hiddenOldCount > 0
232	                            ? `Nenhum lote recente. ${hiddenOldCount} lote(s) antigo(s) oculto(s) — use "Mostrar lotes antigos".`
233	                            : 'Nenhum lote neste estoque.'}
234	                    </div>
235	                ) : (
236	                    visibleBatches.map(batch => {
237	                        const status = getExpiryStatus(batch.data_validade);
238	                        const StatusIcon = status.icon;
239	                        return (
240	                            <div key={batch.id} className="flex flex-col sm:flex-row items-start sm:items-center justify-between p-3 bg-white/60 dark:bg-black/40 rounded-lg border border-[#57715B]/10 gap-3">
241	                                <div className="flex-1 space-y-1">
242	                                    <div className="flex items-center gap-2">
243	                                        <span className="font-mono font-bold text-sm text-foreground">{batch.codigo}</span>
244	                                        <Badge variant="outline" className={cn("text-[10px] h-5 px-1.5 gap-1", status.color)}>
245	                                            <StatusIcon className="w-3 h-3" />
246	                                            Val: {formatDate(batch.data_validade)}
247	                                        </Badge>
248	                                        {batch.data_fabricacao && (
249	                                            <Badge variant="outline" className="text-[10px] h-5 px-1.5 gap-1 text-gray-500 border-gray-200">
250	                                                Fab: {formatDate(batch.data_fabricacao)}
251	                                            </Badge>
252	                                        )}
253	                                    </div>
254	                                    <div className="text-[10px] text-muted-foreground uppercase tracking-wider font-bold">
255	                                        {status.label}
256	                                    </div>
257	                                </div>
258	                            </div>
259	                        );
260	                    })
261	                )}
262	            </div>
263	        </div>
264	    );
265	}
