20	// Calcula font-size ideal para etiqueta de loja (60mm × 40mm, padding 2mm → área útil 56mm × 36mm)
21	// Respeita quebras de linha manuais (\n): a linha mais longa determina a largura mínima,
22	// e o total de linhas determina a altura necessária.
23	const getStoreLabelFontSize = (text: string): string => {
24	    const upper = (text || '').toUpperCase();
25	    const lines = upper.split('\n').filter(l => l.trim().length > 0);
26	    // IMPORTANTE: reduce começa com '' para pegar o máximo por linha, não o texto todo concatenado
27	    const longestLine = lines.reduce((a, b) => (a.length > b.length ? a : b), '');
28	    const maxLen = (longestLine.trim().length) || 1;
29	    const lineCount = Math.max(lines.length, 1);
30	
31	    // Bold uppercase Arial em 56mm: char_width ≈ pt × 0.353mm × 0.63
32	    // → chars_per_line = 56 / (pt × 0.353 × 0.63) = 251 / pt
33	    // lineHeight=1.15: line_height_mm = pt × 0.353 × 1.15
34	    // → lines_avail = 36 / (pt × 0.353 × 1.15) = 88.6 / pt
35	    for (let pt = 24; pt >= 7; pt--) {
36	        const charsPerLine = Math.floor(251 / pt);
37	        const linesAvail = Math.floor(88.6 / pt);
38	        if (maxLen <= charsPerLine && lineCount <= linesAvail) return `${pt}pt`;
39	    }
40	    return '7pt';
41	};
